const data = items[0]?.json || {};
const leads = Array.isArray(data.items) ? data.items : [];
const now = new Date();
const twoHours = 2 * 60 * 60 * 1000;
const fortyEightHours = 48 * 60 * 60 * 1000;

const updates = [];
for (const lead of leads) {
  const last = lead.lastInteraction ? new Date(lead.lastInteraction) : null;
  if (!last) continue;
  const diff = now - last;
  // Cold logic (48h) — skip Won/Lost
  if (diff > fortyEightHours && lead.status !== 'WON' && lead.status !== 'LOST' && lead.status !== 'COLD') {
    updates.push({ json: { id: lead.id, newStatus: 'COLD' } });
    continue;
  }
  // Needs Followup (2h) — skip Won/Lost/Cold
  if (diff > twoHours && lead.status !== 'WON' && lead.status !== 'LOST' && lead.status !== 'COLD' && lead.status !== 'NEEDS_FOLLOWUP') {
    updates.push({ json: { id: lead.id, newStatus: 'NEEDS_FOLLOWUP' } });
  }
}
return updates;
